const pkKnifeOn=()=>!!(S.opt&&S.opt.pkKnife);
const RCN=RC.map(c=>parseInt(c.slice(1),16)),knR=()=>curKn().r;
const QT=["Easy","Medium","Hard","Brutal"],QTC=["#4ade80","#60a5fa","#fbbf24","#f0abfc"],QN=12,QMIX=[4,4,3,1],QSW=3,QSKIP=[40,110,260,550];
const qDayKey=()=>{const d=new Date();return d.getFullYear()*10000+(d.getMonth()+1)*100+d.getDate()};
const qNextRot=()=>{const d=new Date();d.setHours(24,0,0,0);return d.getTime()};
// one fresh quest of tier t that is not already on the board
function qPick(t,have){
let pool=QU.filter(q=>q.t===t&&!have.has(q.n));if(!pool.length)pool=QU.filter(q=>!have.has(q.n));if(!pool.length)return null;
const q=pk(pool);have.add(q.n);return{k:q.k,n:q.n,need:q.need,xp:q.xp,t:q.t,mx:!!q.mx,p:0}}
// keeps the board at exactly 12 valid quests (old single-quest saves move onto it)
function questFill(){
if(!Array.isArray(S.qb))S.qb=[];
if(S.aq&&typeof S.aq==="object"&&S.aq.k){S.qb.unshift({k:S.aq.k,n:S.aq.n,need:S.aq.need,xp:S.aq.xp,t:S.aq.t,mx:!!S.aq.mx,p:(S.q&&S.q[S.aq.k])|0});S.aq=null;S.q={}}
let seen=new Set();const ok=[];
for(const q of S.qb){if(!q||typeof q.k!=="string"||typeof q.n!=="string"||!(q.need>0)||seen.has(q.n))continue;seen.add(q.n);
ok.push({k:q.k,n:String(q.n).slice(0,80),need:Math.min(9999,q.need|0)||1,xp:clamp(q.xp|0,1,5000),t:clamp(q.t|0,0,3),mx:!!q.mx,p:clamp(+q.p||0,0,q.need)})}
S.qb=ok.slice(0,QN);
// rotation: once per local day every quest you have not touched is swapped for a fresh one, and the free switches come back
const dk=qDayKey();
if(S.qday!==dk){if(S.qday){seen=new Set(S.qb.map(q=>q.n));S.qb=S.qb.map(q=>{if(q.p>0)return q;seen.delete(q.n);const n=qPick(q.t,seen);if(n)return n;seen.add(q.n);return q});S.qseen=0}S.qday=dk;S.qsw=QSW}
S.qsw=clamp(S.qsw==null?QSW:S.qsw|0,0,QSW);
const cnt=[0,0,0,0];S.qb.forEach(q=>cnt[q.t]++);
while(S.qb.length<QN){let t=0;for(let i=1;i<4;i++)if(QMIX[i]-cnt[i]>QMIX[t]-cnt[t])t=i;const q=qPick(t,seen);if(!q)break;S.qb.push(q);cnt[q.t]++}
return S.qb}
// Battle Pass curve: the first tiers drop in minutes (~90 XP), the climb stays gentle (tier 30 costs ~860), 30 tiers are ~14k XP in total.
// Matches, waves, bosses and kills pay most of it; quests are a bonus on top. After tier 30 the pass keeps paying coins (BP_OVER).
const BP_TIERS=150,BP_XP=[0],BP_OVER=[1200,100];for(let i=1;i<=BP_TIERS;i++)BP_XP[i]=BP_XP[i-1]+Math.round(110+Math.min(i,60)*5+Math.max(0,i-60)*1.5); // early tiers come quickly, the late game settles at about 500 XP a tier
// six chapters of 25 tiers, each with its own colour on the track
const BP_CH=[["Rookie","#4ade80"],["Contender","#38bdf8"],["Veteran","#a78bfa"],["Elite","#f472b6"],["Champion","#fbbf24"],["Legend","#f97316"]];
// swap one quest for a new one of the same tier; limited to QSW free switches per day
function qSwap(i){
const q=S.qb[i];if(!q||(S.qsw|0)<=0)return false;
const have=new Set(S.qb.map(x=>x.n)),nq=qPick(q.t,have);if(!nq||nq.n===q.n)return false;
S.qb[i]=nq;S.qsw=(S.qsw|0)-1;sv();return true}
// pay coins to finish a quest on the spot and collect its Battle Pass XP
const qSkipCost=q=>QSKIP[clamp(q.t|0,0,3)];
function qSkip(i){
const q=S.qb[i];if(!q||q.p>=q.need)return false;const c=qSkipCost(q);if(S.coins<c)return false;
S.coins-=c;q.p=q.need;questDone([q]);return true}
