const bKey=n=>/^(__proto__|constructor|prototype)$/.test(n)?n+"_":n;
const boardOf=n=>{n=bKey(n);const h=Object.prototype.hasOwnProperty;if(!h.call(S.board,n)||!S.board[n])S.board[n]={w:0,k:0};return S.board[n]};
