const wkKey=()=>{const d=new Date(),t=new Date(d.getFullYear(),d.getMonth(),d.getDate());t.setDate(t.getDate()-(t.getDay()+6)%7);return t.getFullYear()*10000+(t.getMonth()+1)*100+t.getDate()};
