const SQ=[{k:"kills",n:"Get 1,000 kills",need:1000,xp:4000,c:600},{k:"heads",n:"Land 300 headshots",need:300,xp:3500,c:500},{k:"wins",n:"Win 60 matches",need:60,xp:5000,c:700},{k:"play",n:"Finish 150 matches",need:150,xp:4500,c:600},{k:"cases",n:"Open 40 cases",need:40,xp:3000,c:800},{k:"wave",n:"Reach wave 25 in Monster Rush",need:25,xp:4000,c:600,mx:1},{k:"boss",n:"Defeat 30 bosses in Monster Rush",need:30,xp:4000,c:600},{k:"wc",n:"Clear 200 waves in Monster Rush",need:200,xp:3500,c:500},{k:"pk",n:"Finish 40 Parkour courses",need:40,xp:3500,c:500},{k:"coin",n:"Earn 8,000 coins from matches",need:8000,xp:3000,c:500},{k:"mk",n:"Defeat 800 monsters",need:800,xp:3000,c:500},{k:"pwin",n:"Win 15 Party matches",need:15,xp:3500,c:500}];
